100	
101	        // The selected claims of the sheet, in list order.
102	        List<Person> everyone = people.list(id);
103	        List<Claim> all = claims.list(id);
104	        List<Claim> ordered = new ArrayList<>();
105	        for (Person p : everyone) {
106	            for (Claim c : all) {
107	                if (c.getPersonId() == p.getId() && selected.contains(c.getId())) ordered.add(c);
108	            }
109	        }
110	
111	        int opened = 0;
112	        Rollup before = Rollup.of(id, people, claims, rates, sheets, settings);
113	        for (Claim claim : ordered) {
114	            try {
115	                periods.requireOpen(id, claim.getDate());
116	                claim.setStatus(ClaimStatus.valueOf(claim.getStatus()).moveTo(ClaimStatus.OPEN).name());
117	            } catch (ClaimStatusException | PeriodClosedException refused) {
118	                continue;
119	            }
120	            claim.setNumber(ClaimNumbers.next(claim, claims, periods, settings, sheets));
121	            claim.setOpenedBy(user);
122	            claims.update(claim);
123	            log.record(claim, user);
124	            opened++;
125	            Person person = everyone.stream().filter((p) -> p.getId() == claim.getPersonId())
126	                    .findFirst().orElse(null);
127	            audit.record(ClaimStatus.OPEN.event() + " sheet=" + id + " by=" + user
128	                    + " person=" + (person == null ? "" : person.getName())
129	                    + " amount=" + claim.getAmount() + " date=" + claim.getDate()
130	                    + claim.getAuditNumber());
131	            Rollup after = Rollup.of(id, people, claims, rates, sheets, settings);
132	            for (String line : after.changesSince(before, id, user)) {
133	                audit.record(line);
134	            }
135	            before = after;
136	        }
137	        result.set(new BulkOpenResult(opened, selected.size() - opened));
138	    }
