232	        String date = request == null || request.date() == null ? "" : request.date().trim();
233	        String note = request == null || request.note() == null ? "" : request.note().trim();
234	        String corrects = request == null || request.corrects() == null ? "" : request.corrects().trim();
235	        if (!AMOUNT.matcher(amount).matches()) {
