745	public final class Dues {
746	    private Dues() {
747	    }
748	
749	    /** What a late charge goes by: the sheet's late percent by date (a claim goes by the one in force on its date) and its today (a claim's due-by is its own); and the
750	     *  sheet's policy date (its today when blank), which decides how a claim's live figures round. */
751	    public record Late(DatedSetting pct, LocalDate today, LocalDate policy) {
752	
753	        /** How the live figures of a claim round by its round date ({@link Claim#getRoundDate}):
754	         *  half up before the policy date, half to even on or after it. */
755	        public RoundingMode rounding(String roundDate) {
756	            return LocalDate.parse(roundDate).isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
757	        }
758	    }
759	
760	    /** An amount times a percent, divided by 100, rounded ({@code rounding}) to two decimals, and at
761	     *  least {@code floor}, the sheet's floor in force on the claim's date (a correction, a negative amount, has no floor). */
762	    public static String of(String amount, String pct, String floor, RoundingMode rounding) {
763	        BigDecimal due = new BigDecimal(amount).multiply(new BigDecimal(pct))
764	                .divide(BigDecimal.valueOf(100), 2, rounding);
765	        return (isCorrection(amount) ? due : due.max(new BigDecimal(floor).setScale(2))).toPlainString();
766	    }
767	
768	    /** Whether a claim's amount makes it a correction: it is negative. */
769	    public static boolean isCorrection(String amount) {
770	        return new BigDecimal(amount).signum() < 0;
771	    }
772	
773	    /** The late charge on a claim's figure: the late percent of it for every full 30 days its open (OPEN or PENDING)
774	     *  claim is past its due-by (fixed when it was added) on the sheet's today, rounded by the
775	     *  policy date to two decimals; none (0.00) when it is not overdue (a deferred claim never is), or on a correction. */
776	    public static BigDecimal charge(Claim claim, String figure, Late late) {
777	        if (figure == null || isCorrection(claim.getAmount()) || !ClaimStatus.isOpen(claim.getStatus()) || claim.isDeferred()) return BigDecimal.ZERO.setScale(2);
778	        LocalDate dueBy = LocalDate.parse(claim.getDueBy());
779	        long periods = Math.max(0, ChronoUnit.DAYS.between(dueBy, late.today())) / 30;
780	        return new BigDecimal(figure).multiply(new BigDecimal(late.pct().on(claim.getDate())))
781	                .multiply(BigDecimal.valueOf(periods))
782	                .divide(BigDecimal.valueOf(100), 2, late.rounding(claim.getRoundDate()));
783	    }
784	
785	    /** The due a claim shows: the one fixed when settled, else its figure (bound by a statement, else
786	     *  {@code live}; null: none) with its late charge added on top. */
787	    public static String shown(Claim claim, String live, Late late) {
788	        if (claim.getSettledDue() != null) return claim.getSettledDue();
789	        String figure = claim.due(live);
790	        return figure == null ? null : new BigDecimal(figure).add(charge(claim, figure, late)).toPlainString();
791	    }
