654	/** The sheet's figures at one moment, as the screen shows them: each person's claimed and
655	 *  due-total (null: n/a; else at most the sheet's cap) and overdue-total, in the order they were added, and the
656	 *  sheet's claimed-total, due-total and overdue-total. */
657	public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal, String overdueTotal) {
658	    /** A person's figures: their name, claimed, due-total (null: n/a) and overdue-total (the shown
659	     *  dues of their open claims past their due-by on the sheet's today, n/a ones skipped). */
660	    public record Figures(String name, String claimed, String dueTotal, String overdueTotal) {
661	        public boolean sameAs(Figures other) {
662	            return other != null && claimed.equals(other.claimed)
663	                    && (dueTotal == null ? other.dueTotal == null : dueTotal.equals(other.dueTotal))
664	                    && overdueTotal.equals(other.overdueTotal);
665	        }
666	    }
667	    /** The sheet's figures now. */
668	    public static Rollup of(String sheetId, PersonRepository people, ClaimRepository claims,
669	            RateRepository rates, SheetRepository sheets, SettingRepository settings) {
670	        List<Rate> sheetRates = rates.list(sheetId);
671	        DatedSetting floor = settings.floor(sheetId);
672	        BigDecimal cap = settings.cap(sheetId);
673	        LocalDate todayDate = sheets.today(sheetId);
674	        String today = todayDate.toString();
675	        Dues.Late late = settings.late(sheetId, todayDate);
676	        List<Claim> all = claims.list(sheetId);
677	        Map<Long, Figures> figures = new LinkedHashMap<>();
678	        BigDecimal claimedTotal = zero();
679	        BigDecimal dueTotal = zero();
680	        BigDecimal overdueTotal = zero();
681	        for (Person p : people.list(sheetId)) {
682	            BigDecimal claimed = zero();
683	            BigDecimal due = zero();
684	            BigDecimal overdue = zero();
685	            boolean kept = false;
686	            for (Claim c : all) {
687	                if (c.getPersonId() != p.getId() || !p.countsLive(c)) continue;
688	                claimed = claimed.add(new BigDecimal(c.getAmount()));
689	                String grade = p.gradeOn(c.getDate());
690	                String pct = rateOn(sheetRates, grade, c.getDate());
691	                String d = Dues.shown(c, pct == null ? null : Dues.of(c.getAmount(), pct, floor.on(c.getDate()), late.rounding(c.getRoundDate())), late);
692	                kept |= c.getSettledDue() != null || c.isBound()
693	                        || (pct != null && (!grade.equals(p.getGrade()) || c.getDate().compareTo(today) <= 0));
694	                if (d != null) due = due.add(new BigDecimal(d));
695	                if (d != null && ClaimStatus.isOpen(c.getStatus()) && c.getDueBy().compareTo(today) < 0) {
696	                    overdue = overdue.add(new BigDecimal(d));
697	                }
698	            }
699	            boolean na = rateOn(sheetRates, p.getGrade(), today) == null && !kept;
700	            if (cap != null && due.compareTo(cap) > 0) due = cap.setScale(2);
701	            figures.put(p.getId(), new Figures(p.getName(), claimed.toPlainString(),
702	                    na ? null : due.toPlainString(), overdue.toPlainString()));
703	            claimedTotal = claimedTotal.add(claimed);
704	            if (!na) dueTotal = dueTotal.add(due);
705	            overdueTotal = overdueTotal.add(overdue);
706	        }
707	        return new Rollup(figures, claimedTotal.toPlainString(), dueTotal.toPlainString(),
708	                overdueTotal.toPlainString());
709	    }
710	    /** The audit lines after a change from {@code before} to this: one ROLLUP per person whose
711	     *  figures moved (a new person counts as moved), then TOTALS when a sheet total moved. */
712	    public List<String> changesSince(Rollup before, String sheetId, String by) {
713	        String head = " sheet=" + sheetId + " by=" + by;
714	        List<String> lines = new ArrayList<>();
715	        people.forEach((id, now) -> {
716	            if (!now.sameAs(before.people.get(id))) {
717	                lines.add("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed()
718	                        + " due-total=" + (now.dueTotal() == null ? "n/a" : now.dueTotal())
719	                        + " overdue-total=" + now.overdueTotal());
720	            }
721	        });
722	        if (!claimedTotal.equals(before.claimedTotal) || !dueTotal.equals(before.dueTotal)
723	                || !overdueTotal.equals(before.overdueTotal)) {
724	            lines.add("TOTALS" + head + " claimed-total=" + claimedTotal + " due-total=" + dueTotal
725	                    + " overdue-total=" + overdueTotal);
726	        }
727	        return lines;
728	    }
729	    /** The grade's rate in force on the date (yyyy-MM-dd): the one with the latest from-date on or
730	     *  before it; null when there is none, or that one ended (its to-date) before the date. */
731	    private static String rateOn(List<Rate> rates, String grade, String date) {
732	        Rate found = null;
733	        for (Rate r : rates) {
734	            if (!r.grade().equals(grade) || (r.from() != null && r.from().compareTo(date) > 0)) continue;
735	            if (found == null || nz(found.from()).compareTo(nz(r.from())) < 0) found = r;
736	        }
737	        return found == null || found.endedBefore(date) ? null : found.pct();
738	    }
739	    private static String nz(String from) {
740	        return from == null ? "" : from;
741	    }
742	    private static BigDecimal zero() {
743	        return BigDecimal.ZERO.setScale(2);
744	    }
745	}
