756	/**
757	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
758	 * so tests can assert side-effects by reading that file — the second test-assertion channel
759	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
760	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
761	 *
762	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
763	 * SYNC) so a test reads the record immediately.
764	 */
765	@Service
766	public class Audit {
767	    private final Path file;
768	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
769	        this.file = Path.of(path);
770	    }
771	    /** Append one audit record. Tests assert the exact line(s) in the file. */
772	    public synchronized void record(String entry) {
773	        try {
774	            Path parent = file.toAbsolutePath().getParent();
775	            if (parent != null) {
776	                Files.createDirectories(parent);
777	            }
778	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
779	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
780	        } catch (IOException e) {
781	            throw new UncheckedIOException(e);
782	        }
783	    }
784	    /** Remove the audit file. */
785	    public synchronized void clear() {
786	        try {
787	            Files.deleteIfExists(file);
788	        } catch (IOException e) {
789	            throw new UncheckedIOException(e);
790	        }
791	    }
792	}
