879	            PersonRepository people, SheetRepository sheets, ClaimRepository claims,
880	            PeriodRepository periods, SettingRepository settings, ClaimLogRepository log, Audit audit,
881	            Out<PasteResult> result) throws PeriodClosedException, InvalidClaimException {
882	        String id = sheetId.trim();
