885	        for (PasteLine line : lines.lines()) {
886	            Person person = people.findByName(id, line.name());
887	            if (person == null) {
888	                throw new InvalidClaimException("Not on the sheet: " + line.name());
889	            }
890	            ValidClaim request = line.claim();
891	            LocalDate date = request.date() != null ? request.date() : sheets.today(id);
892	            if (person.retiredBefore(date)) {
