475	export const SETTING_DEFAULTS: Record<string, string> = { floor: '1.00', terms: '14', 'late-pct': '0.00' };
476	
477	/** The settings that are not dated: every other one is saved from a from-date (blank: the sheet's today). */
478	export const UNDATED_KEYS: readonly string[] = ['policy-date', 'period-numbering-from'];
479	
480	/** A dated setting's value in force on a date (yyyy-MM-dd). */
481	export type DatedOn = (date: string) => string;
482	
483	/** A setting's value in force on a date (yyyy-MM-dd): the one with the latest from-date on or before
484	 *  it; else its starting value (SETTING_DEFAULTS), and none (undefined) for a key with none. */
485	export function settingOn(settings: Setting[] | undefined, key: string, date: string): string | undefined {
486	  let found: Setting | undefined;
487	  for (const s of settings ?? []) {
488	    if (s.key !== key || (s.from !== null && s.from > date)) continue;
489	    if (found === undefined || (found.from ?? '') < (s.from ?? '')) found = s;
490	  }
491	  return found === undefined ? SETTING_DEFAULTS[key] : found.value;
492	}
493	
494	const base = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}`;
495	
496	export const settingsKey = (sheetId: string) => [...sheetKey(sheetId), 'settings'] as const;
497	export const rolesKey = (sheetId: string) => [...sheetKey(sheetId), 'roles'] as const;
498	
499	export function listSettings(sheetId: string): Promise<Setting[]> {
500	  return getJson<Setting[]>(`${base(sheetId)}/settings`);
501	}
502	
503	/** Change a setting; refused (rejects) when the value is not valid for it. */
504	export function changeSetting(sheetId: string, by: string, key: string, value: string, from: string): Promise<Setting> {
505	  return postJson<Setting>(`${base(sheetId)}/settings?by=${encodeURIComponent(by)}`, { key, value, from });
506	}
507	
508	export function listRoles(sheetId: string): Promise<Role[]> {
509	  return getJson<Role[]>(`${base(sheetId)}/roles`);
510	}
511	
512	/** Assign a user name a role; refused (rejects) when the role is not clerk or steward. */
513	export function setRole(sheetId: string, by: string, user: string, role: string): Promise<Role> {
514	  return postJson<Role>(`${base(sheetId)}/roles?by=${encodeURIComponent(by)}`, { user, role });
515	}
516	
517	/** The sheet's floor by date: the least a claim's live due can be, the one in force on its date. */
518	export function useFloor(sheetId: string): DatedOn {
519	  const settings = useQuery({ queryKey: settingsKey(sheetId), queryFn: () => listSettings(sheetId) });
520	  return (date) => settingOn(settings.data, 'floor', date) || SETTING_DEFAULTS.floor;
521	}
522	
523	/** The sheet's cap in force on its today: the most a person's due-total can be; null when there is none. */
524	export function useCap(sheetId: string, today: string): string | null {
525	  const settings = useQuery({ queryKey: settingsKey(sheetId), queryFn: () => listSettings(sheetId) });
526	  return settingOn(settings.data, 'cap', today) || null;
527	}
528	
529	/** What a claim's late charge and rounding go by: the sheet's late percent by date (a claim goes
530	 *  by the one in force on its date), today and policy date (its today when blank). */
531	export function useLate(sheetId: string, today: string): Late {
532	  const settings = useQuery({ queryKey: settingsKey(sheetId), queryFn: () => listSettings(sheetId) });
533	  const pct = (date: string) => settingOn(settings.data, 'late-pct', date) || SETTING_DEFAULTS['late-pct'];
534	  const policy = settingOn(settings.data, 'policy-date', today) || today;
535	  return { pct, today, policy };
536	}
537	import { useQuery } from '@tanstack/react-query';
538	import { postJson } from '../../api/http';
539	
540	/** `today` is the sheet's own date (yyyy-MM-dd): every date decision and default uses it. */
541	export type Sheet = { id: string; createdBy: string; today: string };
542	
543	/** Load a sheet by id; the server starts it empty the first time the id is used. */
544	export function openSheet(id: string, by: string): Promise<Sheet> {
545	  return postJson<Sheet>(
546	    `/api/sheets/${encodeURIComponent(id)}/open?by=${encodeURIComponent(by)}`,
547	    {},
548	  );
549	}
550	
551	/** Change the sheet's today; refused (rejects) when it is not a date. */
552	export function setSheetToday(id: string, by: string, today: string): Promise<Sheet> {
553	  return postJson<Sheet>(
554	    `/api/sheets/${encodeURIComponent(id)}/today?by=${encodeURIComponent(by)}`,
555	    { today },
556	  );
557	}
558	
559	/** Every query about a sheet lives under this key, so loading it again re-reads all of it. */
560	export const sheetKey = (id: string) => ['sheet', id] as const;
561	
562	/** The loaded sheet's today, read from the sheet query `ActiveSheet` keeps; '' until loaded. */
563	export function useSheetToday(id: string, by: string): string {
564	  const sheet = useQuery({ queryKey: sheetKey(id), queryFn: () => openSheet(id, by) });
565	  return sheet.data?.today ?? '';
