import { getJson, postJson } from '../../api/http';
import { counts, dueBy, isBound, isCorrection, isOverdue, type Claim } from '../claims/api';
import { sheetKey } from '../sheet/api';
import type { DatedOn } from '../settings/api';

/** A grade's rate on the sheet: a percent as two-decimal text, in force from its from-date
 *  (yyyy-MM-dd; null applies from the beginning of time) through its to-date (null: no end). A grade
 *  with no rate is not listed. */
export type Rate = { sheetId: string; grade: string; pct: string; from: string | null; to: string | null };
/** A blank `from` sets the rate that applies from the beginning of time; a blank `to` has no end. */
export type RateInput = { grade: string; pct: string; from: string; to: string };

const base = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/rates`;

export const ratesKey = (sheetId: string) => [...sheetKey(sheetId), 'rates'] as const;

/** The sheet's rates, by grade, then by from-date (none first). */
export function listRates(sheetId: string): Promise<Rate[]> {
  return getJson<Rate[]>(base(sheetId));
}

/** Set a grade's rate from a from-date, replacing the one with the same grade and from-date;
 *  refused (rejects) when the percent is missing, negative or has more than two decimals, or the
 *  from-date or to-date is not a date, or the to-date is before the from-date. */
export function setRate(sheetId: string, by: string, input: RateInput): Promise<Rate> {
  return postJson<Rate>(`${base(sheetId)}?by=${encodeURIComponent(by)}`, input);
}

/** The grade's rate in force on a date (yyyy-MM-dd): the one with the latest from-date on or
 *  before it; undefined (n/a) when the date is before every rate the grade has, or it has none, or
 *  that one ended (its to-date) before the date. */
export function rateOn(rates: Rate[] | undefined, grade: string, date: string): string | undefined {
  let found: Rate | undefined;
  for (const r of rates ?? []) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  return found === undefined || (found.to !== null && found.to < date) ? undefined : found.pct;
}

/** The rate in force on a date for each grade that has one then. */
export function rateByGrade(rates: Rate[] | undefined, date: string): Map<string, string> {
  const byGrade = new Map<string, string>();
  for (const r of rates ?? []) {
    const pct = rateOn(rates, r.grade, date);
    if (pct !== undefined) byGrade.set(r.grade, pct);
  }
  return byGrade;
}

/** Two-decimal text (may be negative) as a whole number of hundredths. */
function hundredths(text: string): bigint {
  const t = text.trim();
  const negative = t.startsWith('-');
  const [whole, frac = ''] = (negative ? t.slice(1) : t).split('.');
  const value = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -value : value;
}

/** An amount times a percent, divided by 100, rounded to two decimals (half up when `halfUp`, else
 *  half to even), and at least the sheet's `floor` (a correction, a negative amount, has no floor);
 *  null (n/a) when there is no rate. Exact: worked in whole hundredths. */
export function dueOf(amount: string, pct: string | undefined, floor: string, halfUp: boolean): string | null {
  if (pct === undefined) return null;
  // amount (1/100) x pct (1/100) / 100 is in 1/1_000_000; to cents is / 10_000.
  const cents = roundPct(hundredths(amount) * hundredths(pct), halfUp);
  const least = hundredths(floor);
  return formatCents(cents < least && hundredths(amount) >= 0n ? least : cents);
}

/** What a claim's late charge goes by: the sheet's late percent by date (a claim goes by the one in force on its date) and its today (a claim's due-by is its own);
 *  and the sheet's policy date (its today when blank), which decides how a claim's live figures round. */
export type Late = { pct: DatedOn; today: string; policy: string };

/** Whether a claim's live figures round half up: its round date (its own, or for a correction the
 *  date of the claim it corrects) is before the policy date; else they round half to even. */
export const roundsHalfUp = (c: Claim, late: Late) => (c.roundDate ?? c.date) < late.policy;

/** The late charge on an open (OPEN or PENDING) claim's `figure`: the late percent of it for every full 30 days it is
 *  past its due-by on the sheet's today, rounded by the policy date to two decimals (0 when not overdue, and
 *  on a correction). */
export function lateCharge(c: Claim, figure: string, late: Late): bigint {
  if (isCorrection(c) || !isOverdue(c, late.today)) return 0n;
  const days = (Date.parse(`${late.today}T00:00:00Z`) - Date.parse(`${dueBy(c)}T00:00:00Z`)) / 86_400_000;
  return roundPct(hundredths(figure) * hundredths(late.pct(c.date)) * BigInt(Math.floor(days / 30)), roundsHalfUp(c, late));
}

/** A person's grade in force on a date (yyyy-MM-dd). */
export type GradeOn = (date: string) => string;

/** A claim's due: the one fixed when it was settled (its late charge then frozen in), else its
 *  figure — the one bound by its person's last statement (not while PENDING; n/a when it bound none), else live at the rate in force on the
 *  claim's date of the grade in force then (`gradeOn`), at least the `floor` in force then — with its late charge
 *  on the sheet's today on top. */
export function claimDue(c: Claim, rates: Rate[] | undefined, gradeOn: GradeOn, floor: DatedOn, late: Late): string | null {
  if (c.settledDue !== null) return c.settledDue;
  const figure = c.stated && c.status !== 'PENDING' ? c.statedDue : dueOf(c.amount, rateOn(rates, gradeOn(c.date), c.date), floor(c.date), roundsHalfUp(c, late));
  return figure === null ? null : formatCents(hundredths(figure) + lateCharge(c, figure, late));
}

/** A product of hundredths and a percent's hundredths (in 1/1_000_000) to cents, half up (away
 *  from zero) when `halfUp`, else half to even (symmetric about zero). */
function roundPct(product: bigint, halfUp: boolean): bigint {
  if (product < 0n) return -roundPct(-product, halfUp);
  const whole = product / 10_000n;
  const rest = product % 10_000n;
  return rest > 5_000n || (rest === 5_000n && (halfUp || whole % 2n === 1n)) ? whole + 1n : whole;
}

/** A person's due-total: the sum of their counting claims' due figures (n/a ones skipped), at
 *  most the sheet's `cap` (null: no cap); n/a
 *  when their grade today has no rate today (`pct`) and none of those claims keeps a settled or bound
 *  figure, or a live one at a grade no longer in force on the sheet's today or dated on or before it
 *  (its rate since ended). */
export function personDue(claims: Claim[], rates: Rate[] | undefined, gradeOn: GradeOn, pct: string | undefined,
  floor: DatedOn, late: Late, cap: string | null) {
  const own = claims.filter(counts);
  const now = gradeOn(late.today);
  const kept = (c: Claim) => c.settledDue !== null || isBound(c)
    || ((gradeOn(c.date) !== now || c.date <= late.today) && rateOn(rates, gradeOn(c.date), c.date) !== undefined);
  if (pct === undefined && !own.some(kept)) return null;
  const sum = sumDues(own.map((c) => claimDue(c, rates, gradeOn, floor, late)));
  return cap !== null && hundredths(sum) > hundredths(cap) ? formatCents(hundredths(cap)) : sum;
}

/** What a person's due figures add up to above the sheet's `cap` (null: no cap); 0.00 when they do
 *  not exceed it, or their due-total is n/a. */
export function excessOf(claims: Claim[], rates: Rate[] | undefined, gradeOn: GradeOn, pct: string | undefined,
  floor: DatedOn, late: Late, cap: string | null): string {
  const full = personDue(claims, rates, gradeOn, pct, floor, late, null);
  return full === null || cap === null || hundredths(full) <= hundredths(cap) ? '0.00'
    : formatCents(hundredths(full) - hundredths(cap));
}

/** The overdue claims among those that count (`claims`, the live ones): their count and the sum
 *  of their due figures (n/a ones skipped). */
export function overdue(claims: Claim[], today: string, dueOfClaim: (c: Claim) => string | null) {
  const late = claims.filter((c) => isOverdue(c, today));
  return { count: late.length, total: sumDues(late.map(dueOfClaim)) };
}

/** Add up two-decimal dues, skipping n/a. */
export function sumDues(dues: Array<string | null>): string {
  return formatCents(dues.reduce<bigint>((t, d) => (d === null ? t : t + hundredths(d)), 0n));
}

function formatCents(cents: bigint): string {
  const abs = cents < 0n ? -cents : cents;
  const frac = (abs % 100n).toString().padStart(2, '0');
  return `${cents < 0n ? '-' : ''}${abs / 100n}.${frac}`;
}

/** A due as shown: n/a when there is none. */
export const showDue = (due: string | null) => due ?? 'n/a';
import { getJson, postJson, putJson } from '../../api/http';
import { sheetKey } from '../sheet/api';

/** A claim's status: DRAFT, opened to OPEN, settled to SETTLED (or, by a clerk above the clerk limit,
 *  to PENDING, which a steward approves to SETTLED or rejects back to OPEN); a DRAFT, OPEN or PENDING
 *  claim can be voided. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';
/** A change of a claim's status. */
export type ClaimAction = 'open' | 'settle' | 'void' | 'approve' | 'reject' | 'resettle';

/** Whether a claim is open: OPEN, or PENDING a steward's approval. */
export const isOpen = (c: Pick<Claim, 'status'>) => c.status === 'OPEN' || c.status === 'PENDING';

/** Whether a statement's figure binds a claim now: it was bound to one and is not PENDING (a PENDING
 *  claim shows and totals its live figure until it is rejected). */
export const isBound = (c: Claim) => c.stated && c.statedDue !== null && c.status !== 'PENDING';

/** A claim: its amount as two-decimal text, its date (yyyy-MM-dd), its note, its status and its
 *  number on the sheet (given when opened: the sheet-wide 1, 2, ... or, under period numbering,
 *  <period>-<n> or X-<n>; null while a draft), and its settled due
 *  (fixed when settled; null otherwise, or when there was no rate then — its due stays live), and who
 *  opened it (null while a draft; that user cannot settle it), and whether its person's last statement
 *  bound it, with the figure it bound (null when it had none): a bound claim shows and totals that.
 *  A correction (a negative amount) has the number of the SETTLED claim it corrects (null otherwise).
 *  `roundDate` is the date its live figures round by: its own, or a correction's claim's it corrects.
 *  `dueBy` (yyyy-MM-dd) is fixed when it was added: its date then plus the terms of its person's
 *  grade in force on that date (the grade's own, else the sheet's). `log` is its status log, oldest
 *  first: `<STATUS> by <user> on <date> due=<due>`, the sheet's today and its due at each change.
 *  `deferredUntil` is the date it was last deferred until (null: never), and `deferred` whether it is
 *  deferred on the sheet's today (OPEN and deferred until a later date): a deferred claim counts in no
 *  total, is not overdue, cannot be settled and is left unbound by a statement. */
export type Claim = {
  id: number; sheetId: string; personId: number; amount: string; date: string; note: string; status: ClaimStatus;
  number: string | null; settledDue: string | null; openedBy: string | null;
  stated: boolean; statedDue: string | null; corrects: string | null; roundDate: string; dueBy: string;
  log: string[]; deferredUntil: string | null; deferred: boolean;
};
/** `corrects`: the number of the SETTLED claim of the same person a correction (a negative amount) corrects. */
export type ClaimInput = { amount: string; date: string; note: string; corrects: string };

/** Whether a claim is a correction: its amount is negative. */
export const isCorrection = (c: Pick<Claim, 'amount'>) => c.amount.trim().startsWith('-') && Number(c.amount) !== 0;

const sheetBase = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}`;

export const claimsKey = (sheetId: string) => [...sheetKey(sheetId), 'claims'] as const;

/** Every claim on the sheet, newest first. */
export function listClaims(sheetId: string): Promise<Claim[]> {
  return getJson<Claim[]>(`${sheetBase(sheetId)}/claims`);
}

/** Add a claim to a person; refused (rejects) when the amount is missing or has more than two
 *  decimals, the date is not a date, or it is a correction (negative) that does not name by number a
 *  SETTLED claim of the person. A blank date takes the sheet's today. */
export function addClaim(sheetId: string, by: string, personId: number, input: ClaimInput): Promise<Claim> {
  return postJson<Claim>(`${sheetBase(sheetId)}/people/${personId}/claims?by=${encodeURIComponent(by)}`, input);
}

/** Edit a claim; refused (rejects) like an add. */
export function updateClaim(sheetId: string, by: string, id: number, input: ClaimInput): Promise<Claim> {
  return putJson<Claim>(`${sheetBase(sheetId)}/claims/${id}?by=${encodeURIComponent(by)}`, input);
}

/** Change a claim's status; refused (rejects) when its status does not allow the change, when the
 *  user settling or approving it is the one who opened it, when a non-steward approves or rejects it,
 *  or when a rejection has no `reason`. A steward's `resettle` freezes a SETTLED claim again at the
 *  figure it would have today as an open claim bound by no statement. */
export function moveClaim(sheetId: string, by: string, id: number, action: ClaimAction, reason = ''): Promise<Claim> {
  const extra = action === 'reject' ? `&reason=${encodeURIComponent(reason)}` : '';
  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/${action}?by=${encodeURIComponent(by)}${extra}`, {});
}

/** Defer an OPEN claim until a date after the sheet's today; refused (rejects) when it is not OPEN,
 *  the date is not after today, or it is dated in a closed period. */
export function deferClaim(sheetId: string, by: string, id: number, until: string): Promise<Claim> {
  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/defer?by=${encodeURIComponent(by)}&until=${encodeURIComponent(until)}`, {});
}

/** A steward moves a DRAFT, OPEN or PENDING claim to another person (`toPersonId`): it keeps its
 *  number and date, loses any figure a statement bound it to, and is listed as that person's newest
 *  claim. Refused (rejects) for anyone else, for a SETTLED or VOID claim, or one dated in a closed period. */
export function reassignClaim(sheetId: string, by: string, id: number, toPersonId: number): Promise<Claim> {
  return postJson<Claim>(`${sheetBase(sheetId)}/claims/${id}/reassign?by=${encodeURIComponent(by)}&to=${toPersonId}`, {});
}

/** Whether a claim counts toward claimed, due-total and every total: only OPEN, PENDING and SETTLED do. */
export const counts = (c: Claim) => isOpen(c) || c.status === 'SETTLED';

/** The claims that count in live totals: all but the deferred claims and the open claims dated within one of their
 *  person's holds (`to` null: open-ended) that no statement bound (SETTLED and bound claims still count). */
export function liveClaims(claims: Claim[],
  people: Array<{ id: number; holds: Array<{ from: string; to: string | null }> }> | undefined): Claim[] {
  const holds = new Map((people ?? []).map((p) => [p.id, p.holds]));
  const held = (c: Claim) => (holds.get(c.personId) ?? []).some((h) => h.from <= c.date && (h.to === null || c.date <= h.to));
  return claims.filter((c) => !c.deferred && !(isOpen(c) && !c.stated && held(c)));
}

/** Sum the amounts of the claims that count (see `counts`) exactly (in cents), shown with two decimals. */
export function sumAmounts(claims: Claim[]): string {
  const cents = claims.filter(counts).reduce((t, c) => t + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}

/** A claim's due-by (yyyy-MM-dd), fixed when it was added. */
export const dueBy = (c: Claim): string => c.dueBy;

/** Whether a claim is overdue: it is open (OPEN or PENDING), not deferred, and its due-by is before the sheet's `today`. */
export const isOverdue = (c: Claim, today: string) =>
  isOpen(c) && !c.deferred && today !== '' && dueBy(c) < today;

/** How many of the selected claims a bulk open opened, and how many it refused (left as they were). */
export type BulkOpenResult = { opened: number; refused: number };

/** Open the selected claims together, numbered in list order (people in added order, newest claim
 *  first within a person); each that cannot be opened is left as it is and counted as refused. */
export function bulkOpenClaims(sheetId: string, by: string, claimIds: number[]): Promise<BulkOpenResult> {
  return postJson<BulkOpenResult>(`${sheetBase(sheetId)}/bulk-open?by=${encodeURIComponent(by)}`, { claimIds });
}

/** How many of the selected claims a bulk settle settled (one gone to PENDING counts), and how many
 *  it refused (left as they were). */
export type BulkSettleResult = { settled: number; refused: number };

/** Settle the selected claims together in list order (people in added order, newest claim first
 *  within a person), each by the rules of settling one; each that cannot be settled is left as it is
 *  and counted as refused. */
export function bulkSettleClaims(sheetId: string, by: string, claimIds: number[]): Promise<BulkSettleResult> {
  return postJson<BulkSettleResult>(`${sheetBase(sheetId)}/bulk-settle?by=${encodeURIComponent(by)}`, { claimIds });
}

/** How many claims a paste added. */
export type PasteResult = { added: number };

/** Add a DRAFT claim per line of name,amount,date,note (the note may hold commas; a blank date takes
 *  the sheet's today; the note may be absent), in order, to the named person; refused (rejects),
 *  adding nothing, when any line would be refused by the claim form or names no one on the sheet. */
export function pasteClaims(sheetId: string, by: string, text: string): Promise<PasteResult> {
  return postJson<PasteResult>(`${sheetBase(sheetId)}/paste-claims?by=${encodeURIComponent(by)}`, { text });
}
import { getJson, postJson, putJson } from '../../api/http';
import { sheetKey } from '../sheet/api';
import type { Claim } from '../claims/api';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/** A grade a person was given, in force from its from-date (yyyy-MM-dd; null: from the beginning of time). */
export type GradeFrom = { grade: Grade; from: string | null };

/** A hold on a person: from its from-date to its to-date (null: open-ended), both included (yyyy-MM-dd). */
export type Hold = { from: string; to: string | null };

/** `grade` is the one in force on the sheet's today, of their `grades` by from-date (none first).
 *  `version` is raised by every saved edit; an edit sends the version its form loaded. Their
 *  statements: how many were taken, and the last one's due-total and date (null until the first).
 *  `retiredFrom` is the date they are retired from (null: not retired); with it set at all they
 *  are `retired`, whatever the date. `holds` are their holds in the order added, and `held` whether
 *  they have any: their OPEN claims dated within a hold, and not bound by a statement, count in no
 *  live total. `patronIds` are the people they name
 *  as patrons, in the order named. */
export type Person = {
  id: number; sheetId: string; name: string; grade: Grade; grades: GradeFrom[]; version: number;
  statementCount: number; statedTotal: string | null; statementDate: string | null;
  retired: boolean; retiredFrom: string | null; held: boolean; holds: Hold[]; patronIds: number[];
};
/** `gradeFrom` is the date an edit's grade applies from (blank: the sheet's today). */
export type PersonInput = { name: string; grade: string; gradeFrom: string };

/** The person's grade in force on a date (yyyy-MM-dd): the one with the latest from-date on or before it. */
export function gradeOn(p: Person, date: string): string {
  let found: GradeFrom | undefined;
  for (const g of p.grades) {
    if (g.from !== null && g.from > date) continue;
    if (found === undefined || (found.from ?? '') < (g.from ?? '')) found = g;
  }
  return found?.grade ?? '';
}

const base = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/people`;

