                  from <span data-testid="person-retired-from">{p.retiredFrom ?? ''}</span>{' '}
                  <input type="date" data-testid="person-retire-date" value={retireDates[p.id] ?? ''}
                    onChange={(e) => {
                      setRetireDates((d) => ({ ...d, [p.id]: e.target.value }));
                      retirement.reset();
