                  <input type="date" data-testid="person-hold-from" value={holdDates[p.id]?.from ?? ''}
                    onChange={(e) => changeHold(p.id, { from: e.target.value })} />{' '}
                  <input type="date" data-testid="person-hold-to" value={holdDates[p.id]?.to ?? ''}
