                  onChange={(e) => {
                    setDeferDates((d) => ({ ...d, [c.id]: e.target.value }));
                    if (deferral.variables?.id === c.id) deferral.reset();
                  }} />{' '}
                <button type="button" data-testid="claim-defer" disabled={deferral.isPending}
                  onClick={() => defer(c.id)}>
                  Defer
                </button>{' '}
